const MatchHistoryManager = {
  storageKey: 'katar_match_history_replays_v1',
  maxSavedMatches: 25,

  getAll() {
    try {
      const raw = SafeStorage.getItem(this.storageKey);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  },

  saveAll(list) {
    try {
      const trimmed = Array.isArray(list) ? list.slice(0, this.maxSavedMatches) : [];
      SafeStorage.setItem(this.storageKey, JSON.stringify(trimmed));
    } catch (e) {}
    this.renderLists();
  },

  restoreAll(list) {
    if (!Array.isArray(list)) return;
    this.saveAll(list);
  },

  saveCompletedMatch(winner) {
    if (!Array.isArray(GameState.replayFrames) || GameState.replayFrames.length < 2) return;
    const lastFrame = GameState.replayFrames[GameState.replayFrames.length - 1];
    if (GameState.lastFormedMill) lastFrame.lastFormedMill = [...GameState.lastFormedMill];
    if (GameState.gomokuWinningLine) lastFrame.gomokuWinningLine = [...GameState.gomokuWinningLine];

    const [p1Title, p2Title] = getThemePlayerNames();
    const presetLabels = {
      '6x6': '6×6 Katar',
      'navakankari_9': 'Navakankari 9',
      'navakankari_12': '12-Men Katar Mill',
      'three_morris': 'Teen Guti 3v3',
      'six_morris': 'Chhah Guti 6v6',
      'bagh_chal': 'Bagh-Chal',
      'aadu_puli': 'Aadu Puli Attam',
      'lau_kata_kati': 'Lau Kata Kati',
      'pretwa': 'Pretwa Circular',
      'fanorona_5x5': 'Fanorona 5×5',
      'fanorona_5x9': 'Fanorona 5×9',
      'seega_5x5': 'Seega 5×5',
      'dama_8x8': 'Dama 8×8 Kings',
      'gomoku_9x9': 'Gomoku 9×9',
      '37_sholo': '37-Pt Sholo Guti',
      '6x7': '6×7 Maidaan',
      '5x5': '5×5 Baro Guti',
      '5x7': '5×7 Extended',
      '7x7': '7×7 Grand',
      '8x8': '8×8 Commander',
      '4x4': '4×4 Blitz'
    };
    const entry = {
      id: 'M-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      savedAt: Date.now(),
      gameTitle: presetLabels[GameState.gridPreset] || `${GameState.rows}×${GameState.cols} Katar`,
      gameFamily: GameState.gameFamily,
      morrisVariant: GameState.morrisVariant,
      morrisDiagonals: Boolean(GameState.morrisDiagonals),
      gridPreset: GameState.gridPreset,
      rows: GameState.rows,
      cols: GameState.cols,
      hasTriangularCamps: Boolean(GameState.hasTriangularCamps),
      diagonalMode: GameState.diagonalMode,
      piecesPerPlayer: GameState.piecesPerPlayer,
      tigerCaptureTarget: GameState.tigerCaptureTarget,
      p1Name: p1Title,
      p2Name: p2Title,
      winner: winner,
      winReason: GameState.winReason || '',
      capturedBy: { ...GameState.capturedBy },
      movesCount: Math.max(1, GameState.replayFrames.length - 1),
      frames: GameState.replayFrames.map((f) => ({
        step: f.step,
        label: f.label,
        board: [...f.board],
        kings: [...f.kings],
        reserves: { ...f.reserves },
        capturedBy: { ...f.capturedBy },
        currentTurn: f.currentTurn,
        lastMove: f.lastMove ? { ...f.lastMove } : null,
        lastFormedMill: f.lastFormedMill ? [...f.lastFormedMill] : null,
        gomokuWinningLine: f.gomokuWinningLine ? [...f.gomokuWinningLine] : null
      }))
    };

    const list = this.getAll();
    list.unshift(entry);
    this.saveAll(list);
  },

  deleteMatch(matchId) {
    const list = this.getAll().filter((m) => m && m.id !== matchId);
    this.saveAll(list);
  },

  clearAll() {
    this.saveAll([]);
  },

  renderLists() {
    const list = this.getAll();
    const badgeMenu = document.getElementById('badgeMenuReplayCount');
    if (badgeMenu) badgeMenu.textContent = String(list.length);

    const containers = [
      { el: document.getElementById('savedReplaysListProfile'), sourceModal: 'modalProfile' },
      { el: document.getElementById('savedReplaysListEnc'), sourceModal: 'modalEncyclopedia' }
    ];

    for (const { el, sourceModal } of containers) {
      if (!el) continue;
      if (list.length === 0) {
        el.innerHTML = '<div class="text-[11px] text-walnut-500 italic py-2 text-center">No completed matches saved yet — finish a match to watch its replay anytime!</div>';
        continue;
      }
      el.innerHTML = list.map((m) => {
        const dateObj = new Date(m.savedAt || Date.now());
        const dateStr = dateObj.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + ' ' + dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        const isP1Win = m.winner === 1;
        const isP2Win = m.winner === 2;
        const badgeCls = isP1Win
          ? 'bg-teal-100 text-teal-900 border-teal-300'
          : (isP2Win ? 'bg-rose-100 text-rose-900 border-rose-300' : 'bg-amber-100 text-amber-900 border-amber-300');
        const outcomeTxt = isP1Win
          ? `🏆 ${m.p1Name || 'P1'} Won`
          : (isP2Win ? `🏅 ${m.p2Name || 'P2'} Won` : '🤝 Draw');
        const scoreTxt = `${(m.capturedBy && m.capturedBy[1]) || 0} - ${(m.capturedBy && m.capturedBy[2]) || 0}`;
        return `
          <div class="flex items-center justify-between gap-2 bg-parchment-100/90 hover:bg-parchment-200/70 border border-parchment-300 rounded-xl px-2.5 py-1.5 transition-colors">
            <div class="min-w-0 flex-1">
              <div class="flex items-center gap-1.5 flex-wrap">
                <span class="text-[9.5px] font-extrabold px-1.5 py-0.5 rounded-md border ${badgeCls}">${outcomeTxt}</span>
                <span class="text-[11px] font-extrabold text-walnut-900 truncate">${m.gameTitle || 'Katar'}</span>
                <span class="text-[10px] font-mono font-bold text-walnut-600">(${scoreTxt})</span>
              </div>
              <div class="text-[10px] text-walnut-600 truncate mt-0.5">
                ${m.p1Name || 'P1'} vs ${m.p2Name || 'P2'} • <strong>${m.movesCount || 0} moves</strong> • ${dateStr}
              </div>
            </div>
            <div class="flex items-center gap-1 shrink-0">
              <button type="button" data-watch-match-id="${m.id}" data-source-modal="${sourceModal}" class="btn-watch-saved-replay android-btn px-2.5 py-1 rounded-lg bg-gradient-to-b from-indigo-500 to-indigo-700 hover:from-indigo-400 hover:to-indigo-600 text-white text-[10px] font-extrabold shadow flex items-center gap-1">
                <span>🎬</span><span>Replay</span>
              </button>
              <button type="button" data-del-match-id="${m.id}" class="btn-del-saved-replay android-btn w-6 h-6 rounded-lg bg-white hover:bg-rose-50 text-walnut-500 hover:text-rose-700 border border-parchment-300 flex items-center justify-center text-[10px] font-bold" title="Delete Saved Replay">✕</button>
            </div>
          </div>
        `;
      }).join('');

      el.querySelectorAll('.btn-watch-saved-replay').forEach((btn) => {
        btn.addEventListener('click', () => {
          const id = btn.getAttribute('data-watch-match-id');
          const src = btn.getAttribute('data-source-modal');
          SoundEngine.select();
          ReplayManager.playSavedMatchById(id, src);
        });
      });

      el.querySelectorAll('.btn-del-saved-replay').forEach((btn) => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const id = btn.getAttribute('data-del-match-id');
          SoundEngine.select();
          this.deleteMatch(id);
          showBoardToast('Removed match replay from history');
        });
      });
    }
  }
};

function recordSessionOutcome(winner) {
  if (winner === 1) GameState.sessionStats.p1Wins++;
